import ghidra.app.script.GhidraScript;
import java.io.*;
import java.util.*;
public class N3DExportMessageMaps extends GhidraScript {
 public void run() throws Exception {
  String dir=getScriptArgs()[0];Set<Integer> seen=new HashSet<>();Set<String> candidates=new TreeSet<>();
  try(PrintWriter maps=new PrintWriter(dir+"/message_maps.tsv");PrintWriter entries=new PrintWriter(dir+"/message_entries.tsv")){
   maps.println("map\tbase_map\tentries\tcount\tsentinel");
   entries.println("map\tentry\tselector0\tselector1\tsignature\thandler\texisting_entry");
   for(int root:new int[]{0x10,0x16,0x2a,0x40,0x56,0x6c}){
    int cur=root;
    while(cur!=0 && seen.add(cur)){
     var m=toAddr(String.format("1048:%04x",cur));int base=getShort(m)&0xffff;
     int off=getShort(m.add(2))&0xffff,seg=getShort(m.add(4))&0xffff;
     var first=toAddr(String.format("%04x:%04x",seg,off));int count=0;var a=first;
     for(;count<512;count++,a=a.add(10)){
      int s0=getShort(a)&0xffff,s1=getShort(a.add(2))&0xffff,sig=getShort(a.add(4))&0xffff;
      if(sig==0)break;
      int targetOff=getShort(a.add(6))&0xffff,targetSeg=getShort(a.add(8))&0xffff;
      String target=String.format("%04x:%04x",targetSeg,targetOff);boolean known=getFunctionAt(toAddr(target))!=null;
      entries.println(m+"\t"+a+"\t"+s0+"\t"+s1+"\t"+sig+"\t"+target+"\t"+known);
      if(!known)candidates.add(target);
     }
     if(count==512)throw new Exception("No signature-zero sentinel: "+m);
     maps.println(m+"\t"+String.format("1048:%04x",base)+"\t"+first+"\t"+count+"\t"+a);
     cur=base;
    }
   }
  }
  try(PrintWriter p=new PrintWriter(dir+"/message_candidates.txt")){for(String a:candidates)p.println(a);}
 }
}

