import ghidra.app.script.GhidraScript;
import ghidra.program.model.data.*;
import ghidra.program.model.symbol.*;
import ghidra.program.model.listing.*;
import java.nio.file.*;
import java.util.*;
public class N3DDefineMessageMaps extends GhidraScript {
 public void run() throws Exception {
  String dir=getScriptArgs()[0];
  StructureDataType entry=new StructureDataType("N3D_AFX_MESSAGE_ENTRY16_PROVEN",0);
  for(String n:new String[]{"selector0","selector1","signature","handler_offset","handler_selector"})entry.add(WordDataType.dataType,n,null);
  var et=currentProgram.getDataTypeManager().addDataType(entry,DataTypeConflictHandler.DEFAULT_HANDLER);
  StructureDataType map=new StructureDataType("N3D_AFX_MESSAGE_MAP16_PROVEN",0);
  for(String n:new String[]{"base_map_near","entries_offset","entries_selector"})map.add(WordDataType.dataType,n,null);
  var mt=currentProgram.getDataTypeManager().addDataType(map,DataTypeConflictHandler.DEFAULT_HANDLER);
  var rows=Files.readAllLines(Paths.get(dir+"/message_entries.tsv"));int count=0;
  for(String line:rows.subList(1,rows.size())){
   String[] c=line.split("\t");var a=toAddr(c[1]);var t=toAddr(c[5]);
   if((getShort(a.add(4))&0xffff)!=Integer.parseInt(c[4]))throw new Exception("Signature differs "+a);
   clearListing(a,a.add(9));createData(a,et);
   currentProgram.getReferenceManager().addMemoryReference(a.add(6),t,RefType.DATA,SourceType.USER_DEFINED,0);count++;
  }
  rows=Files.readAllLines(Paths.get(dir+"/message_maps.tsv"));
  for(String line:rows.subList(1,rows.size())){
   String[] c=line.split("\t");var a=toAddr(c[0]);clearListing(a,a.add(5));createData(a,mt);
   var sentinel=toAddr(c[4]);if((getShort(sentinel.add(4))&0xffff)!=0)throw new Exception("Bad sentinel "+sentinel);
   clearListing(sentinel,sentinel.add(9));createData(sentinel,et);
   currentProgram.getReferenceManager().addMemoryReference(a.add(2),toAddr(c[2]),RefType.DATA,SourceType.USER_DEFINED,0);
   if(!c[1].equals("1048:0000"))currentProgram.getReferenceManager().addMemoryReference(a,toAddr(c[1]),RefType.DATA,SourceType.USER_DEFINED,0);
  }
  println("PROVEN_MESSAGE_ENTRIES "+count+" maps="+(rows.size()-1));
 }
}
